evidence.quote:
.settings-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 23px;
}

.connected-main-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(260px, 1fr);
  gap: 20px;
}

.connected-desk > [data-slot="button"] {
  margin-top: auto;
  width: 100%;
}

--radius-sm: 0.25rem;
  --radius-md: 0.375rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.75rem;

.empty-state {
  border: 1px dashed #424c33;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 75px 25px;

.empty-state p {
  font-size: 12px;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 10px;
  color: #ccb991;
  line-height: 1.6;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 8px;
  line-height: 1.6;
  font-weight: 600;
  letter-spacing: 0.17em;
  text-transform: uppercase;

.catalog-filters {
  gap: 1px;
}

.connected-stat small {
  display: block;
  color: #a0aa8e;
  font-size: 9px;

a:focus-visible,
button:focus-visible,
summary:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 4px;
}
